import {readFile,writeFile} from 'node:fs/promises';
import {generatedNativeScriptHostVersions} from './Scripts/MiniApps/resolve-upstreams.mjs';
const locked=JSON.parse(await readFile('Scripts/NativeScript/dependency-lock.json','utf8'));
const input={nativescript:{'@nativescript/ios':locked.nativeScript.iosRuntimeVersion,'@nativescript/core':locked.nativeScript.coreVersion,'@nativescript/swift-ui':locked.swiftUI.version}};
await writeFile('Packages/HanlinNativeScriptRuntime/Sources/HanlinNativeScriptRuntime/HanlinNativeScriptHostVersions.swift',generatedNativeScriptHostVersions(input));
console.log(JSON.stringify(input));
